#!/usr/bin/env node
/**
 * Generates src/lib/repo-facts.json — the real numbers the landing page's
 * "Verify, do not trust" section renders.
 *
 * Not wired into `build`: Vercel builds from a shallow clone with no circuit
 * artifacts, so the generated file is committed and regenerated by hand
 * (`bun run gen-repo-facts`) whenever circuits or the commit history move.
 */
import { createHash } from "node:crypto";
import { readFileSync, writeFileSync, readdirSync, statSync } from "node:fs";
import { execFileSync } from "node:child_process";
import { join, dirname, relative } from "node:path";
import { fileURLToPath } from "node:url";

const web = join(dirname(fileURLToPath(import.meta.url)), "..");

/** Repos behind the trust claims, ordered by how much they matter to a verifier. */
const REPOS = [
  { key: "programs", dir: "../solana-programs" },
  { key: "circuits", dir: "../circuits-src" },
  { key: "web", dir: "." },
];

const git = (dir, ...args) => execFileSync("git", args, { cwd: dir, encoding: "utf8" });

/** Skips repos that aren't checked out beside web/ — the JSON is committed anyway. */
function repoFacts() {
  const out = [];
  for (const { key, dir } of REPOS) {
    const path = join(web, dir);
    try {
      const url = git(path, "remote", "get-url", "origin").trim();
      out.push({
        key,
        name: url.replace(/^.*github\.com[:/]/, "").replace(/\.git$/, ""),
        url: `https://github.com/${url.replace(/^.*github\.com[:/]/, "").replace(/\.git$/, "")}`,
        head: git(path, "rev-parse", "HEAD").trim().slice(0, 7),
      });
    } catch {
      console.warn(`repo-facts: skipping ${key} (${dir} is not a checkout)`);
    }
  }
  return out;
}

/** sha256 of every Groth16 artifact served to the browser. */
function circuitArtifacts() {
  const root = join(web, "public/circuits/groth16");
  const out = [];
  const walk = (dir) => {
    for (const name of readdirSync(dir)) {
      const p = join(dir, name);
      if (statSync(p).isDirectory()) walk(p);
      else if (/\.(zkey|vkey\.json|wasm)$/.test(name)) {
        out.push({
          path: relative(join(web, "public"), p),
          sha256: createHash("sha256").update(readFileSync(p)).digest("hex"),
        });
      }
    }
  };
  walk(root);
  return out.sort((a, b) => a.path.localeCompare(b.path));
}

const artifacts = circuitArtifacts();
const repos = repoFacts();
const facts = {
  generatedAt: new Date().toISOString(),
  repos,
  circuitCount: new Set(artifacts.map((a) => a.path.split("/")[2])).size,
  artifacts,
};

writeFileSync(join(web, "src/lib/repo-facts.json"), JSON.stringify(facts, null, 2) + "\n");
console.log(
  `repo-facts: ${repos.map((r) => `${r.key}@${r.head}`).join(" ")}, ` +
    `${facts.artifacts.length} artifacts, ${facts.circuitCount} circuits`,
);
